    fun generateSeedCategories(): List<PictureVocabularyCategoryEntity> {
        return categoriesData.mapIndexed { index, triple ->
            PictureVocabularyCategoryEntity(
                id = triple.first,
                displayNameEnglish = triple.second,
                displayNameArabic = triple.third, // Using the 3rd field as Arabic for this unused file
                displayNameUrdu = triple.third,
                descriptionEnglish = "Learn essential vocabulary for ${triple.second}",
                iconName = triple.first,
                sortOrder = index + 1,
                totalQuestionCount = 26
            )
        }
    }

    fun generateSeedItemsAndQuestions(): Pair<List<PictureVocabularyItemEntity>, List<PictureVocabularyQuestionEntity>> {
        val allItems = mutableListOf<PictureVocabularyItemEntity>()
        val allQuestions = mutableListOf<PictureVocabularyQuestionEntity>()

        categoriesData.forEach { (catId, _, _) ->
            val raws = rawItemsMap[catId] ?: emptyList()
            val catItems = mutableListOf<PictureVocabularyItemEntity>()

            raws.forEachIndexed { idx, raw ->
                val itemId = "${catId}_item_${idx + 1}"
                val item = PictureVocabularyItemEntity(
                    id = itemId,
                    categoryId = catId,
                    wordEnglish = raw.word,
                    wordArabic = com.example.utils.ArabicTranslator.translate(raw.word),
                    wordUrdu = raw.urdu,
                    romanUrdu = raw.roman,
                    exampleSentenceEnglish = raw.exampleEn,
                    exampleSentenceUrdu = raw.exampleUr,
                    imageAssetKey = raw.assetKey,
                    pronunciationText = raw.word,
                    ipa = null,
                    imageUrl = PictureVocabularyImageMap.getImageUrlForWord(raw.word, raw.assetKey),
                    imageSearchQuery = PictureVocabularyImageMap.getSearchQueryForWord(raw.word),
                    alt = PictureVocabularyImageMap.getAltForWord(raw.word)
                )
                catItems.add(item)
                allItems.add(item)
            }

            // Create 26 questions for this category, each targeting one item
            catItems.forEachIndexed { idx, targetItem ->
                val questionId = "${catId}_q_${idx + 1}"
                // Pick 3 distinct distractors from other items in the same category
                val otherItems = catItems.filter { it.id != targetItem.id }.shuffled()
                val distractors = otherItems.take(3)
                val options = (distractors + targetItem).shuffled()
                val optionIdsString = options.joinToString(",") { it.id }
                val sortedOptionIds = options.map { it.id }.sorted().joinToString(",")
                val fingerprint = "SELECT_CORRECT_IMAGE_${catId}_${targetItem.id}_${sortedOptionIds}"

                val question = PictureVocabularyQuestionEntity(
                    id = questionId,
                    categoryId = catId,
                    targetItemId = targetItem.id,
                    optionItemIdsString = optionIdsString,
                    correctItemId = targetItem.id,
                    normalizedFingerprint = fingerprint
                )
                allQuestions.add(question)
            }
        }

        return Pair(allItems, allQuestions)
    }
